syntax:
numbers = [1, 2, 3, 4, 5]

# for: iterate over a sequence
for n in numbers:
    print(n)

# range(): generate a sequence of numbers without building a list
for i in range(5):        # 0, 1, 2, 3, 4
    print(i)
for i in range(2, 5):      # 2, 3, 4 - start, stop (exclusive)
    print(i)

# enumerate(): get both the index and the value while iterating
for index, value in enumerate(numbers):
    print(index, value)

# accumulator pattern: build up a result across iterations
total = 0
for n in numbers:
    total += n

# while: repeat while a condition holds
count = 0
while count < 3:
    print(count)
    count += 1

# loop control
for n in numbers:
    if n == 3:
        continue    # skip the rest of this iteration, go to the next
    if n == 5:
        break         # stop the loop entirely
    print(n)

# nested loops: a loop inside another loop, e.g. for a grid
for row in range(3):
    for col in range(3):
        print(row, col)
